package org.openidentity.protocol.v2;
import org.junit.jupiter.api.Test;import java.util.HexFormat;import static org.junit.jupiter.api.Assertions.*;
final class ProtocolV2DelegationAuthorityLifecycleTest {
 static final HexFormat H=HexFormat.of();
 static final String V309_PREV="a70103025820000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f0301040105a201010281a20150000102030405060708090a0b0c0d0e0f02a4010103272006215820a40cc8cce2a052cdf27b8f3c4ef2c9dcf68576dfcee74902d5fff23f4f35eb0c08a1010009a10100",V309_SIGNED="",V309_STATE="",V309_HASH="1220392757af2f28e9905f90ccc9dbb9bf6d6b45184aa647adc284b324a6fb7f0aa8";
 static final String V310_PREV="",V310_SIGNED="",V310_STATE="",V310_HASH="1220deff427715e9694e30ecf70742b8322b3e4e46f91d94df8a569958b3e4652862";
 static final String V311_PREV="",V311_SIGNED="",V311_STATE="",V311_HASH="12200748381bb54b0278db4fe801ecc1c77d4d69ff84a8e290e1088435a45c4513ac";
 static final String V312_PREV="",V312_SIGNED="",V312_STATE="a70103025820000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f0302040105a201010281a20150000102030405060708090a0b0c0d0e0f02a4010103272006215820dfc2adaecd8e857e2da11401e5bffc987af2d9b235e2ad37ecfbc7e8fec9653e08a1010009a10105",V312_HASH="122011ed85ad865366aa911e12c1819a4f28b6f6a02386c1acf5af6ec3cedb3dab3a";
 static final String V313_PREV="",V313_SIGNED="",V313_STATE="",V313_HASH="12208b42a1490fb3a1017465c90d8e68cad5d3d2b6bfe1e83d00984997e2e341d828";
 static final String V319_PREV="",V319_SIGNED="",V319_STATE="",V319_HASH="122044fbf54ae1ecb7dac5094496ce3b5553fd1146792406fa85f5bf5ad7404b8432";
 static final String V320_PREV="",V320_SIGNED="",V320_STATE="",V320_HASH="12207a79b56827aa14ec77213fb75195da0401f8e234016caa44414035ae2bbe428b";
 static final String V321_PREV="a50102025820000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f0301040105a201010281a20150000102030405060708090a0b0c0d0e0f02a40101032720062158204b2ab800e4b95f6f4c104a898b9652d6dda0ae28799e5dcba8df4a27fc159825",V321_SIGNED="",V321_STATE="",V321_HASH="12205b5236dbfb16a452dd9416901fee02ff080e1faffee84d07086eb4ec13d2dae2";
 @Test void v309(){check(V309_PREV,V309_SIGNED,V309_STATE,V309_HASH);}
 @Test void v310(){check(V310_PREV,V310_SIGNED,V310_STATE,V310_HASH);}
 @Test void v311(){check(V311_PREV,V311_SIGNED,V311_STATE,V311_HASH);}
 @Test void v312(){check(V312_PREV,V312_SIGNED,V312_STATE,V312_HASH);}
 @Test void v313(){check(V313_PREV,V313_SIGNED,V313_STATE,V313_HASH);}
 @Test void v319(){check(V319_PREV,V319_SIGNED,V319_STATE,V319_HASH);}
 @Test void v320(){check(V320_PREV,V320_SIGNED,V320_STATE,V320_HASH);}
 @Test void v321(){check(V321_PREV,V321_SIGNED,V321_STATE,V321_HASH);}
 @Test void tamperedDelegationPopRejected(){byte[] x=H.parseHex(V309_SIGNED);x[x.length-1]^=1;assertThrows(IllegalArgumentException.class,()->ProtocolV2TransitionVerifier.verifyAndApply(H.parseHex(V309_PREV),x));}
 @Test void duplicateDelegationPopRejected(){byte[] x=duplicateField7Proof(V309_SIGNED);assertThrows(IllegalArgumentException.class,()->ProtocolV2TransitionVerifier.verifyAndApply(H.parseHex(V309_PREV),x));}
 @Test void resetDelegationsRequiresV3(){assertThrows(IllegalArgumentException.class,()->ProtocolV2TransitionVerifier.verifyAndApply(H.parseHex("a50102025820000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f0304040105a201010281a20150000102030405060708090a0b0c0d0e0f02a40101032720062158200c00c96d277924dcfeb80d66dc26a3056658188b7d2592b7df1c2f413abf7fd9"),wrapUnsignedOperation(H.parseHex("a601020209035820000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f040505582212201d2f9ce3b9eed807f300c8238985631c4d8bbf6a9bffe214f78b85615033505e06a0"))));}
 private static void check(String p,String s,String state,String hash){var t=ProtocolV2TransitionVerifier.verifyAndApply(H.parseHex(p),H.parseHex(s));assertEquals(state,H.formatHex(t.successorStateBytes()));assertEquals(hash,H.formatHex(t.successorStateHash()));}
 private static byte[] duplicateField7Proof(String signed){var r=new org.openidentity.cbor.StrictCborReader(H.parseHex(signed));r.readMapHeader();r.readUnsigned();byte[] op=r.readEncoded();r.readUnsigned();byte[] cp=r.readEncoded();r.readUnsigned();r.readArrayHeader();byte[] proof=r.readEncoded();var w=new org.openidentity.cbor.DeterministicCborWriter();w.writeMapHeader(3);w.writeUnsigned(1);w.writeEncoded(op);w.writeUnsigned(2);w.writeEncoded(cp);w.writeUnsigned(7);w.writeArrayHeader(2);w.writeEncoded(proof);w.writeEncoded(proof);return w.toByteArray();}
 private static byte[] wrapUnsignedOperation(byte[] op){var w=new org.openidentity.cbor.DeterministicCborWriter();w.writeMapHeader(1);w.writeUnsigned(1);w.writeEncoded(op);return w.toByteArray();}
}
